-- Docker kurz — Kompletní kurz (20 lekcí + závěrečný kvíz)
-- MariaDB 10.4, phpMyAdmin style, no DELIMITER
-- Apostrofy escapovány jako ''

SET @kurs_id = (SELECT id FROM courses WHERE slug = 'docker');

-- ============================================================
-- LEKCE 1–20
-- ============================================================

INSERT INTO lessons (course_id, title, content, lesson_type, sort_order, xp_reward, duration_minutes) VALUES
(@kurs_id, 'Co je Docker', '<h2>Kontejnery vs virtuální stroje</h2><p>Docker je platforma pro kontejnerizaci aplikací. Kontejner je lehký, izolovaný proces, který sdílí jádro hostitelského OS — na rozdíl od virtuálního stroje, který potřebuje celý hostovaný OS. Kontejnery se spouštějí v sekundách, spotřebovávají megabajty místo gigabajtů a jsou ideální pro mikroservisy i monolity.</p><pre><code># Velikost — kontejner vs VM\nVM:        10–40 GB (celý OS)\nKontejner:  50–500 MB (jen aplikace + závislosti)\n\n# Start — kontejner vs VM\nVM:        30–120 sekund\nKontejner:  0.1–2 sekundy</code></pre><h2>Proč Docker</h2><p>Docker řeší problém "funguje u mě, nefunguje na produkci". Aplikace balí všechny závislosti do jednoho image — běží stejně na vývojovém stroji, CI/CD pipeline i produkčním serveru. Eliminuje rozdíly mezi prostředími.</p><pre><code># Bez Dockeru:\n# - Různé verze PHP na dev/prod\n# - Chybějící rozšíření\n# - Konflikty knihoven\n\n# S Dockerem:\ndocker run php:8.2-apache php -v\n# Všude stejný výsledek!</code></pre><h2>Architektura Dockeru</h2><p>Docker používá klient-server architekturu. Klient (<code>docker</code>) komunikuje s daemonem (<code>dockerd</code>) přes REST API. Registry (Docker Hub, ghcr.io) ukládají images.</p><pre><code># Architektura\n\n[ docker CLI ] --REST API--> [ dockerd (daemon) ]\n                                   |\n                          +---------+---------+\n                          |         |         |\n                       images  containers  networks\n                          |\n                    [ Docker Hub / Registry ]\n\n# Ověření běhu daemonu\ndocker info\ndocker version</code></pre>', 'lesson', 1, 15, 12),

(@kurs_id, 'Instalace a Docker Desktop', '<h2>Instalace na Windows</h2><p>Docker Desktop pro Windows využívá WSL2 (Windows Subsystem for Linux) jako backend. Potřebuješ Windows 10 Pro/Enterprise s povoleným Hyper-V a WSL2.</p><pre><code># 1. Povol WSL2 (PowerShell jako admin)\nwsl --install\nwsl --set-default-version 2\n\n# 2. Stáhni a nainstaluj Docker Desktop\n# https://www.docker.com/products/docker-desktop\n\n# 3. Ověř instalaci\ndocker --version\n# Docker version 24.0.7\ndocker compose version\n# Docker Compose version v2.23.0\ndocker run hello-world\n# Hello from Docker!</code></pre><h2>Instalace na Linuxu</h2><pre><code># Ubuntu/Debian\nsudo apt-get update\nsudo apt-get install ca-certificates curl gnupg\n\n# Přidání Docker GPG klíče\nsudo install -m 0755 -d /etc/apt/keyrings\ncurl -fsSL https://download.docker.com/linux/ubuntu/gpg | sudo gpg --dearmor -o /etc/apt/keyrings/docker.gpg\nsudo chmod a+r /etc/apt/keyrings/docker.gpg\n\n# Přidání repozitáře\necho "deb [arch=$(dpkg --print-architecture) signed-by=/etc/apt/keyrings/docker.gpg] https://download.docker.com/linux/ubuntu $(. /etc/os-release &amp;&amp; echo $VERSION_CODENAME) stable" | sudo tee /etc/apt/sources.list.d/docker.list > /dev/null\n\nsudo apt-get update\nsudo apt-get install docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin\n\n# Přidání uživatele do skupiny docker\nsudo usermod -aG docker $USER\nnewgrp docker\n\n# Ověření\ndocker run hello-world</code></pre><h2>Základní příkazy</h2><pre><code># Seznam běžících kontejnerů\ndocker ps\n\n# Seznam všech kontejnerů (včetně zastavených)\ndocker ps -a\n\n# Seznam imagů\ndocker images\n\n# Spuštění kontejneru\ndocker run -d --name muj-web -p 8080:80 nginx\n\n# Zastavení kontejneru\ndocker stop muj-web\n\n# Smazání kontejneru\ndocker rm muj-web\n\n# Smazání image\ndocker rmi nginx\n\n# Zobrazení logů\ndocker logs muj-web\n\n# Vstup do běžícího kontejneru\ndocker exec -it muj-web bash</code></pre>', 'lesson', 2, 15, 15),

(@kurs_id, 'Docker images', '<h2>Co je Docker image</h2><p>Image je šablona pro vytvoření kontejneru — obsahuje OS, runtime, knihovny a aplikaci. Image se skládá z vrstev (layers), které se sdílí mezi různými images, což šetří diskový prostor.</p><pre><code># Stažení image z Docker Hub\ndocker pull php:8.2-apache\ndocker pull nginx:alpine\ndocker pull mariadb:10.4\n\n# Seznam lokálních images\ndocker images\n# REPOSITORY   TAG       IMAGE ID       SIZE\n# php          8.2-apache  abc123def456   450MB\n# nginx        alpine     789ghi012jkl   40MB\n\n# Tagování image\ndocker tag php:8.2-apache vevit/edu-php:latest\ndocker tag myapp:latest ghcr.io/vevit/edu-php:v1.0\n\n# Push do registry\ndocker push vevit/edu-php:latest\ndocker push ghcr.io/vevit/edu-php:v1.0\n\n# Smazání image\ndocker rmi php:8.2-apache\n\n# Vyčištění nepoužívaných images\ndocker image prune\ndocker image prune -a  # smaže i nepoužívané</code></pre><h2>Docker Hub</h2><p>Docker Hub je výchozí veřejný registry. Obsahuje oficiální images (označené "Official Image") a komunitní images. Vždy preferuj oficiální images — jsou pravidelně aktualizovány a bezpečnostně auditovány.</p><pre><code># Hledání image\ndocker search nginx\ndocker search php\n\n# Stažení konkrétní verze\ndocker pull mariadb:10.4\ndocker pull node:20-alpine\ndocker pull python:3.12-slim\n\n# Alpine varianty — menší, bez zbytečností\ndocker pull nginx:alpine      # ~40 MB\ndocker pull nginx:latest      # ~140 MB\n\n# Slim varianty — menší Debian\ndocker pull python:3.12-slim  # ~120 MB\ndocker pull python:3.12        # ~1 GB</code></pre><h2>Inspekce image</h2><pre><code># Detailní informace o image\ndocker inspect php:8.2-apache\n\n# Historie vrstev\ndocker history php:8.2-apache\n\n# Velikost image\ndocker images --format "{{.Repository}}:{{.Tag}} {{.Size}}"</code></pre>', 'lesson', 3, 15, 12),

(@kurs_id, 'Dockerfile', '<h2>Struktura Dockerfile</h2><p>Dockerfile je textový soubor s instrukcemi pro sestavení Docker image. Každá instrukce vytváří novou vrstvu. Instrukce se zpracovávají shora dolů.</p><pre><code># Dockerfile — příklad PHP aplikace\nFROM php:8.2-apache\n\n# Nastavení pracovního adresáře\nWORKDIR /var/www/html\n\n# Instalace systémových balíčků\nRUN apt-get update &amp;&amp; apt-get install -y \\\n    libpng-dev \\\n    libjpeg-dev \\\n    libfreetype6-dev \\\n    &amp;&amp; rm -rf /var/lib/apt/lists/*\n\n# Instalace PHP rozšíření\nRUN docker-php-ext-configure gd --with-freetype --with-jpeg \\\n    &amp;&amp; docker-php-ext-install gd pdo pdo_mysql\n\n# Kopírování zdrojového kódu\nCOPY . /var/www/html/\n\n# Nastavení proměnných prostředí\nENV APP_ENV=production\nENV DB_HOST=mariadb\n\n# Exponování portu\nEXPOSE 80\n\n# Výchozí příkaz\nCMD ["apache2-foreground"]</code></pre><h2>Klíčové instrukce</h2><pre><code># FROM — základní image (vždy jako první)\nFROM php:8.2-apache\nFROM node:20-alpine AS builder\n\n# RUN — spuštění příkazu během buildu\nRUN apt-get update &amp;&amp; apt-get install -y git\nRUN npm install --production\n\n# COPY — kopírování souborů z hostitele do image\nCOPY . /var/www/html/\nCOPY --from=builder /app/dist /usr/share/nginx/html\n\n# WORKDIR — nastavení pracovního adresáře\nWORKDIR /app\n\n# ENV — proměnné prostředí\nENV NODE_ENV=production\nENV DB_HOST=mariadb\n\n# EXPOSE — dokumentace portu (neexportuje!)\nEXPOSE 80\nEXPOSE 443\n\n# CMD — výchozí příkaz při spuštění kontejneru\nCMD ["apache2-foreground"]\nCMD ["php", "-S", "0.0.0.0:8080"]\n\n# ENTRYPOINT — neměnný vstupní bod\nENTRYPOINT ["docker-php-entrypoint"]\n# CMD se předá jako argumenty ENTRYPOINTu</code></pre><h2>Optimalizace Dockerfile</h2><pre><code># ŠPATNĚ — každý RUN vytváří novou vrstvu\nRUN apt-get update\nRUN apt-get install -y git\nRUN apt-get install -y curl\n\n# SPRÁVNĚ — spojení do jedné vrstvy\nRUN apt-get update &amp;&amp; apt-get install -y \\\n    git \\\n    curl \\\n    &amp;&amp; rm -rf /var/lib/apt/lists/*\n\n# Build context — .dockerignore\n# .dockerignore\n.git\nnode_modules\n.env\n*.md</code></pre>', 'lesson', 4, 15, 15),

(@kurs_id, 'Multi-stage builds', '<h2>Princip multi-stage builds</h2><p>Multi-stage build používá více <code>FROM</code> instrukcí — každá vytváří samostatnou fázi. Finální image obsahuje jen to, co potřebuje — build závislosti zůstávají v předchozích fázích a nejsou ve výsledném image.</p><pre><code># Multi-stage — Node.js aplikace\nFROM node:20-alpine AS builder\nWORKDIR /app\nCOPY package*.json ./\nRUN npm ci\nCOPY . .\nRUN npm run build\n\nFROM nginx:alpine\nCOPY --from=builder /app/dist /usr/share/nginx/html\nCOPY nginx.conf /etc/nginx/conf.d/default.conf\nEXPOSE 80\nCMD ["nginx", "-g", "daemon off;"]\n\n# Výsledek: image ~40 MB místo ~1.2 GB!</code></pre><h2>PHP + Apache multi-stage</h2><pre><code># Stage 1 — instalace Composer závislostí\nFROM composer:2 AS composer\nWORKDIR /app\nCOPY composer.json composer.lock ./\nRUN composer install --no-dev --no-scripts --prefer-dist\nCOPY . .\nRUN composer dump-autoload --optimize\n\n# Stage 2 — produkční image\nFROM php:8.2-apache\nWORKDIR /var/www/html\nRUN docker-php-ext-install pdo pdo_mysql gd\nCOPY --from=composer /app/vendor ./vendor\nCOPY . .\nENV APP_ENV=production\nEXPOSE 80\nCMD ["apache2-foreground"]</code></pre><h2>Go multi-stage</h2><pre><code># Stage 1 — kompilace\nFROM golang:1.21-alpine AS builder\nWORKDIR /app\nCOPY go.mod go.sum ./\nRUN go mod download\nCOPY . .\nRUN CGO_ENABLED=0 GOOS=linux go build -o server .\n\n# Stage 2 — minimální produkční image\nFROM alpine:3.18\nRUN apk --no-cache add ca-certificates\nCOPY --from=builder /app/server /usr/local/bin/server\nEXPOSE 8080\nENTRYPOINT ["server"]\n\n# Výsledek: image ~15 MB!</code></pre>', 'lesson', 5, 15, 14),

(@kurs_id, 'Volumes', '<h2>Proč volumes</h2><p>Kontejnery jsou dočasné — po smazání se ztratí všechna data. Volumes umožňují persistentní úložiště, které přežívá restart a smazání kontejneru. Používej volumes pro databáze, uploady, logy.</p><pre><code># Named volumes — spravuje Docker\ndocker run -d --name db -v vevit_db_data:/var/lib/mysql mariadb:10.4\n\n# Seznam volumes\ndocker volume ls\n\n# Detail volume\ndocker volume inspect vevit_db_data\n\n# Smazání volume\ndocker volume rm vevit_db_data\n\n# Vyčištění nepoužívaných volumes\ndocker volume prune</code></pre><h2>Bind mounts</h2><p>Bind mount připojuje konkrétní cestu z hostitele do kontejneru. Ideální pro vývoj — změny na hostiteli se okamžitě projeví v kontejneru.</p><pre><code># Bind mount — vývoj\ndocker run -d --name dev-php \\\n  -v /home/user/project:/var/www/html \\\n  -p 8080:80 \\\n  php:8.2-apache\n\n# Read-only bind mount\ndocker run -d --name nginx \\\n  -v /home/user/config:/etc/nginx:ro \\\n  nginx:alpine\n\n# Pozor na SELinux (Linux) — přidej :z nebo :Z\ndocker run -v /home/user/data:/data:z myapp</code></pre><h2>Volumes v docker-compose.yml</h2><pre><code># docker-compose.yml\nservices:\n  db:\n    image: mariadb:10.4\n    volumes:\n      - db_data:/var/lib/mysql\n      - ./init.sql:/docker-entrypoint-initdb.d/init.sql:ro\n    environment:\n      MYSQL_ROOT_PASSWORD: secret\n\n  php:\n    image: php:8.2-apache\n    volumes:\n      - ./src:/var/www/html\n\nvolumes:\n  db_data:\n    driver: local\n\n# Named volume — Docker spravuje umístění\n# Bind mount — ty určuješ cestu na hostiteli</code></pre>', 'lesson', 6, 15, 12),

(@kurs_id, 'Networking', '<h2>Síťové módy</h2><p>Docker nabízí několik síťových režimů. Výchozí je bridge — kontejnery dostanou vlastní IP adresu a mohou komunikovat mezi sebou. Host režim sdílí síťový stack s hostitelem.</p><pre><code># Bridge — výchozí síť\ndocker run -d --name web -p 8080:80 nginx\n\n# Host — kontejner sdílí síť hostitele\ndocker run -d --network host nginx\n# Pozor: -p flag je ignorován u host sítě\n\n# None — žádná síť\ndocker run -d --network none myapp</code></pre><h2>Vlastní sítě</h2><p>Vlastní bridge síť umožňuje kontejnerům komunikovat pomocí názvů (DNS). Na výchozí bridge síti DNS nefunguje — musíš použít IP adresy.</p><pre><code># Vytvoření sítě\ndocker network create vevit-net\n\n# Spuštění kontejnerů ve vlastní síti\ndocker run -d --name db --network vevit-net mariadb:10.4\ndocker run -d --name web --network vevit-net php:8.2-apache\n\n# Kontejner "web" může přistupovat k "db" přes název:\n# php://db:3306\n\n# Seznam sítí\ndocker network ls\n\n# Inspekce sítě\ndocker network inspect vevit-net\n\n# Smazání sítě\ndocker network rm vevit-net</code></pre><h2>Container DNS</h2><p>Na vlastní síti Docker poskytuje vestavěný DNS server. Kontejnery se mohou referencovat vzájemně podle názvu služby — to je klíčové pro docker-compose.</p><pre><code># PHP se připojuje k MariaDB přes název služby\n$pdo = new PDO(\n    "mysql:host=db;dbname=vevit_db;charset=utf8",\n    "root", "secret"\n);\n\n# "db" se resolveuje na IP kontejneru MariaDB\n# Funguje i po restartu kontejneru (IP se může změnit)\n\n# Alias — kontejner má více názvů\ndocker run -d --name mariadb \\\n  --network vevit-net \\\n  --network-alias database \\\n  mariadb:10.4\n\n# Přístup jako "mariadb" i "database"</code></pre>', 'lesson', 7, 15, 14),

(@kurs_id, 'Docker Compose', '<h2>Co je Docker Compose</h2><p>Docker Compose definuje a spouští multi-kontejnerové aplikace pomocí jednoho YAML souboru. Nahrazuje dlouhé <code>docker run</code> příkazy a usnadňuje správu závislostí mezi službami.</p><pre><code># docker-compose.yml\nversion: "3.8"\n\nservices:\n  php:\n    build:\n      context: .\n      dockerfile: Dockerfile\n    ports:\n      - "8080:80"\n    volumes:\n      - ./src:/var/www/html\n    depends_on:\n      - db\n    environment:\n      DB_HOST: db\n      DB_NAME: vevit_db\n\n  db:\n    image: mariadb:10.4\n    environment:\n      MYSQL_ROOT_PASSWORD: secret\n      MYSQL_DATABASE: vevit_db\n    volumes:\n      - db_data:/var/lib/mysql\n\nvolumes:\n  db_data:</code></pre><h2>Základní příkazy</h2><pre><code># Spuštění (na pozadí)\ndocker compose up -d\n\n# Zastavení\ndocker compose down\n\n# Zastavení a smazání volumes\ndocker compose down -v\n\n# Zobrazení logů\ndocker compose logs\ndocker compose logs -f php  # follow pro jednu službu\n\n# Restart jedné služby\ndocker compose restart php\n\n# Přestavění image\ndocker compose build\ndocker compose build --no-cache\n\n# Seznam běžících služeb\ndocker compose ps\n\n# Spuštění jedné služby\ndocker compose up -d db</code></pre><h2>depends_on</h2><p><code>depends_on</code> určuje pořadí spuštění — db se spustí před php. Nezaručuje ale, že služba je připravena (databáze může ještě běžet init skript). Pro spolehlivé čekání používej healthcheck.</p><pre><code>services:\n  php:\n    depends_on:\n      db:\n        condition: service_healthy\n  db:\n    image: mariadb:10.4\n    healthcheck:\n      test: ["CMD", "mysqladmin", "ping", "-h", "localhost"]\n      interval: 5s\n      timeout: 3s\n      retries: 10</code></pre>', 'lesson', 8, 15, 15),

(@kurs_id, 'Docker Compose — volumes, networks, env', '<h2>Volumes v Compose</h2><p>Named volumes deklaruješ v sekci <code>volumes</code> nejvyšší úrovně. Bind mounts odkazují na cestu hostitele relativně k umístění docker-compose.yml.</p><pre><code>services:\n  db:\n    image: mariadb:10.4\n    volumes:\n      - db_data:/var/lib/mysql        # named volume\n      - ./init.sql:/docker-entrypoint-initdb.d/init.sql:ro  # bind mount\n    environment:\n      MYSQL_ROOT_PASSWORD: secret\n\n  php:\n    build: .\n    volumes:\n      - ./src:/var/www/html           # bind mount pro vývoj\n      - vendor:/var/www/html/vendor   # named volume pro vendor\n\nvolumes:\n  db_data:\n    driver: local\n  vendor:\n    driver: local</code></pre><h2>Networks v Compose</h2><pre><code>services:\n  php:\n    build: .\n    networks:\n      - frontend\n      - backend\n    depends_on:\n      - db\n\n  db:\n    image: mariadb:10.4\n    networks:\n      - backend\n    environment:\n      MYSQL_ROOT_PASSWORD: secret\n\n  nginx:\n    image: nginx:alpine\n    networks:\n      - frontend\n    ports:\n      - "80:80"\n    volumes:\n      - ./nginx.conf:/etc/nginx/conf.d/default.conf:ro\n\nnetworks:\n  frontend:\n    driver: bridge\n  backend:\n    driver: bridge\n    internal: true  # není přístupná zvenčí</code></pre><h2>Environment variables a .env</h2><pre><code># .env soubor (NEcommitovat do Gitu!)\nDB_ROOT_PASSWORD=super_secret_pass\nDB_NAME=vevit_db\nAPP_ENV=production\nAPP_DEBUG=false\n\n# docker-compose.yml — reference na .env\nservices:\n  db:\n    image: mariadb:10.4\n    environment:\n      MYSQL_ROOT_PASSWORD: ${DB_ROOT_PASSWORD}\n      MYSQL_DATABASE: ${DB_NAME}\n    volumes:\n      - db_data:/var/lib/mysql\n\n  php:\n    build:\n      context: .\n      args:\n        APP_ENV: ${APP_ENV}\n    environment:\n      DB_HOST: db\n      DB_NAME: ${DB_NAME}\n      APP_DEBUG: ${APP_DEBUG}\n\nvolumes:\n  db_data:\n\n# .env.example (commitovat)\nDB_ROOT_PASSWORD=change_me\nDB_NAME=vevit_db\nAPP_ENV=development\nAPP_DEBUG=true</code></pre>', 'lesson', 9, 15, 14),

(@kurs_id, 'PHP + Apache v Dockeru', '<h2>Základní PHP+Apache image</h2><p>Oficiální image <code>php:8.2-apache</code> obsahuje PHP s Apache2 a mod_php. Je ideální pro rychlé nasazení PHP aplikací na subdoménách vevit.fun.</p><pre><code># Dockerfile pro edu.vevit.fun\nFROM php:8.2-apache\n\n# Povolení mod_rewrite pro .htaccess\nRUN a2enmod rewrite\n\n# Instalace PHP rozšíření\nRUN apt-get update &amp;&amp; apt-get install -y \\\n    libpng-dev \\\n    libjpeg62-turbo-dev \\\n    libfreetype6-dev \\\n    libzip-dev \\\n    &amp;&amp; rm -rf /var/lib/apt/lists/* \\\n    &amp;&amp; docker-php-ext-configure gd --with-freetype --with-jpeg \\\n    &amp;&amp; docker-php-ext-install gd pdo pdo_mysql zip\n\n# Kopírování aplikace\nCOPY . /var/www/html/\n\n# Nastavení oprávnění\nRUN chown -R www-data:www-data /var/www/html\n\nEXPOSE 80\nCMD ["apache2-foreground"]</code></pre><h2>Konfigurace Apache VirtualHost</h2><pre><code># vhost.conf\n&lt;VirtualHost *:80&gt;\n    ServerName edu.vevit.fun\n    DocumentRoot /var/www/html/public\n\n    &lt;Directory /var/www/html/public&gt;\n        AllowOverride All\n        Require all granted\n    &lt;/Directory&gt;\n\n    # Logy\n    ErrorLog ${APACHE_LOG_DIR}/error.log\n    CustomLog ${APACHE_LOG_DIR}/access.log combined\n&lt;/VirtualHost&gt;</code></pre><h2>Build a spuštění</h2><pre><code># Build\ndocker build -t vevit/edu-php .\n\n# Spuštění\ndocker run -d --name edu-php \\\n  -p 8080:80 \\\n  -v $(pwd)/src:/var/www/html \\\n  -e DB_HOST=mariadb \\\n  -e DB_NAME=vevit_db \\\n  --network vevit-net \\\n  vevit/edu-php\n\n# Ověření\ncurl http://localhost:8080\ndocker logs edu-php</code></pre>', 'lesson', 10, 15, 15),

(@kurs_id, 'MariaDB v Dockeru', '<h2>Databázový kontejner</h2><p>Oficiální MariaDB image podporuje automatickou inicializaci — SQL skripty v <code>/docker-entrypoint-initdb.d/</code> se spustí při prvním startu. Tím vytvoříš databázi, tabulky i výchozí data.</p><pre><code># Spuštění MariaDB\ndocker run -d --name vevit-db \\\n  -e MYSQL_ROOT_PASSWORD=secret \\\n  -e MYSQL_DATABASE=vevit_db \\\n  -e MYSQL_USER=vevit \\\n  -e MYSQL_PASSWORD=vevit_pass \\\n  -v vevit_db_data:/var/lib/mysql \\\n  -v ./database/init.sql:/docker-entrypoint-initdb.d/init.sql:ro \\\n  -p 3306:3306 \\\n  mariadb:10.4\n\n# Připojení klienta\ndocker exec -it vevit-db mysql -uvevit -pvevit_pass vevit_db\n\n# Záloha databáze\ndocker exec vevit-db sh -c "exec mysqldump --all-databases -uroot -psecret" > backup.sql\n\n# Obnova databáze\ndocker exec -i vevit-db sh -c "exec mysql -uroot -psecret" < backup.sql</code></pre><h2>Init SQL skripty</h2><pre><code># /docker-entrypoint-initdb.d/01_schema.sql\nCREATE TABLE IF NOT EXISTS users (\n    id INT AUTO_INCREMENT PRIMARY KEY,\n    jmeno VARCHAR(100) NOT NULL,\n    email VARCHAR(255) NOT NULL UNIQUE,\n    heslo VARCHAR(255) NOT NULL,\n    xp INT DEFAULT 0,\n    level INT DEFAULT 1,\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP\n);\n\n# /docker-entrypoint-initdb.d/02_seed.sql\nINSERT INTO users (jmeno, email, heslo) VALUES\n(''Admin'', ''admin@vevit.fun'', ''$2y$10$hash...'');</code></pre><h2>Healthcheck</h2><pre><code># docker-compose.yml\nservices:\n  db:\n    image: mariadb:10.4\n    environment:\n      MYSQL_ROOT_PASSWORD: ${DB_ROOT_PASSWORD}\n      MYSQL_DATABASE: ${DB_NAME}\n    volumes:\n      - db_data:/var/lib/mysql\n      - ./database:/docker-entrypoint-initdb.d:ro\n    healthcheck:\n      test: ["CMD", "mysqladmin", "ping", "-h", "localhost", "-u", "root", "-p${DB_ROOT_PASSWORD}"]\n      interval: 10s\n      timeout: 5s\n      retries: 10\n      start_period: 30s\n    restart: unless-stopped</code></pre>', 'lesson', 11, 15, 15),

(@kurs_id, 'Nginx jako reverse proxy', '<h2>Princip reverse proxy</h2><p>Nginx jako reverse proxy přijímá HTTP požadavky zvenčí a přesměrovává je na backend kontejnery. Výhody: SSL termination, load balancing, cachování, bezpečnost — backend kontejnery nejsou vystaveny přímo.</p><pre><code># Nginx reverse proxy konfigurace\nupstream php_backend {\n    server php:80;\n}\n\nserver {\n    listen 80;\n    server_name edu.vevit.fun;\n\n    # Redirect HTTP -> HTTPS\n    return 301 https://$host$request_uri;\n}\n\nserver {\n    listen 443 ssl;\n    server_name edu.vevit.fun;\n\n    # SSL certifikáty (Let''s Encrypt)\n    ssl_certificate /etc/nginx/ssl/fullchain.pem;\n    ssl_certificate_key /etc/nginx/ssl/privkey.pem;\n\n    # SSL parametry\n    ssl_protocols TLSv1.2 TLSv1.3;\n    ssl_ciphers HIGH:!aNULL:!MD5;\n    ssl_prefer_server_ciphers on;\n\n    # HSTS\n    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;\n\n    location / {\n        proxy_pass http://php_backend;\n        proxy_set_header Host $host;\n        proxy_set_header X-Real-IP $remote_addr;\n        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;\n        proxy_set_header X-Forwarded-Proto $scheme;\n    }\n\n    # Statické soubory — Nginx obsluhuje přímo\n    location ~* \\.(css|js|png|jpg|jpeg|gif|ico|svg|woff2?)$ {\n        proxy_pass http://php_backend;\n        expires 30d;\n        add_header Cache-Control "public, immutable";\n    }\n\n    # Zákaz přístupu ke skrytým souborům\n    location ~ /\\. {\n        deny all;\n    }\n}</code></pre><h2>Docker Compose s Nginx</h2><pre><code>services:\n  nginx:\n    image: nginx:alpine\n    ports:\n      - "80:80"\n      - "443:443"\n    volumes:\n      - ./nginx/conf.d:/etc/nginx/conf.d:ro\n      - ./nginx/ssl:/etc/nginx/ssl:ro\n      - certbot_webroot:/var/www/certbot:ro\n    networks:\n      - frontend\n    depends_on:\n      php:\n        condition: service_healthy\n    restart: unless-stopped\n\n  php:\n    build: .\n    networks:\n      - frontend\n      - backend\n    # Žádné ports — není přístupný zvenčí!\n\n  db:\n    image: mariadb:10.4\n    networks:\n      - backend\n    # Žádné ports — není přístupný zvenčí!\n\nnetworks:\n  frontend:\n  backend:\n    internal: true\n\nvolumes:\n  certbot_webroot:</code></pre>', 'lesson', 12, 15, 15),

(@kurs_id, 'Registry', '<h2>Docker Hub</h2><p>Docker Hub je výchozí veřejný registry. Podporuje veřejné i privátní repozitáře. Pro VeVit organizaci použij privátní repositáře nebo přepni na GitHub Container Registry.</p><pre><code># Přihlášení\ndocker login\n\n# Tagování image pro Docker Hub\ndocker tag myapp:latest vevit/edu-php:latest\ndocker tag myapp:latest vevit/edu-php:v1.2.0\n\n# Push\ndocker push vevit/edu-php:latest\ndocker push vevit/edu-php:v1.2.0\n\n# Pull na produkčním serveru\ndocker pull vevit/edu-php:latest</code></pre><h2>GitHub Container Registry (ghcr.io)</h2><p>ghcr.io je součástí GitHubu — images jsou propojené s repozitáři. Podporuje GraphQL API, automatické buildy přes GitHub Actions a fine-grained PAT permissions.</p><pre><code># Přihlášení do ghcr.io\ndocker login ghcr.io -u USERNAME -p GITHUB_PAT\n\n# Tag pro ghcr.io\ndocker tag myapp:latest ghcr.io/vevit/edu-php:latest\ndocker tag myapp:latest ghcr.io/vevit/edu-php:sha-$GITHUB_SHA\n\n# Push\ndocker push ghcr.io/vevit/edu-php:latest\n\n# Pull\ndocker pull ghcr.io/vevit/edu-php:latest</code></pre><h2>GitHub Actions — automatický push do ghcr.io</h2><pre><code># .github/workflows/docker-publish.yml\nname: Build &amp; Push Docker Image\n\non:\n  push:\n    branches: [main]\n    tags: ["v*"]\n\nenv:\n  REGISTRY: ghcr.io\n  IMAGE_NAME: vevit/edu-php\n\njobs:\n  build-push:\n    runs-on: ubuntu-latest\n    permissions:\n      contents: read\n      packages: write\n    steps:\n      - uses: actions/checkout@v4\n      - uses: docker/login-action@v3\n        with:\n          registry: ${{ env.REGISTRY }}\n          username: ${{ github.actor }}\n          password: ${{ secrets.GITHUB_TOKEN }}\n      - uses: docker/metadata-action@v5\n        id: meta\n        with:\n          images: ${{ env.REGISTRY }}/${{ env.IMAGE_NAME }}\n          tags: |\n            type=ref,event=branch\n            type=semver,pattern={{version}}\n            type=sha\n      - uses: docker/build-push-action@v5\n        with:\n          context: .\n          push: true\n          tags: ${{ steps.meta.outputs.tags }}\n          labels: ${{ steps.meta.outputs.labels }}</code></pre>', 'lesson', 13, 15, 14),

(@kurs_id, 'Docker pro vývoj', '<h2>Live reload s volumes</h2><p>Pro vývoj používej bind mounts — změny v kódu se okamžitě projeví v kontejneru. Pro PHP aplikace Apache automaticky detekuje změny souborů.</p><pre><code># docker-compose.dev.yml\nservices:\n  php:\n    build:\n      context: .\n      target: development\n    volumes:\n      - ./src:/var/www/html\n    environment:\n      APP_ENV: development\n      APP_DEBUG: "true"\n    ports:\n      - "8080:80"\n\n  db:\n    image: mariadb:10.4\n    environment:\n      MYSQL_ROOT_PASSWORD: dev_pass\n      MYSQL_DATABASE: vevit_dev\n    volumes:\n      - db_dev_data:/var/lib/mysql\n    ports:\n      - "3306:3306"\n\nvolumes:\n  db_dev_data:</code></pre><h2>Xdebug v Dockeru</h2><pre><code># Dockerfile — development target\nFROM php:8.2-apache as development\n\nRUN pecl install xdebug \\\n    &amp;&amp; docker-php-ext-enable xdebug\n\nCOPY docker/php/xdebug.ini /usr/local/etc/php/conf.d/xdebug.ini\n\n# xdebug.ini\n# zend_extension=xdebug.so\n# xdebug.mode=debug\n# xdebug.start_with_request=trigger\n# xdebug.client_host=host.docker.internal\n# xdebug.client_port=9003\n# xdebug.discover_client_host=true\n# xdebug.log=/tmp/xdebug.log\n\n# Pozor: na Linuxu použij --add-host\n# docker run --add-host=host.docker.internal:host-gateway ...</code></pre><h2>VS Code Remote Containers</h2><p>Dev Containers umožňují otevřít projekt přímo v Docker kontejneru z VS Code. Všechny nástroje, rozšíření a terminál běží uvnitř kontejneru.</p><pre><code># .devcontainer/devcontainer.json\n{\n  "name": "VeVit Edu Dev",\n  "dockerComposeFile": ["../docker-compose.dev.yml"],\n  "service": "php",\n  "workspaceFolder": "/var/www/html",\n  "customizations": {\n    "vscode": {\n      "extensions": [\n        "xdebug.php-debug",\n        "bmewburn.vscode-intelephense-client",\n        "mtxr.sqltools",\n        "ms-azuretools.vscode-docker"\n      ],\n      "settings": {\n        "php.validate.executablePath": "/usr/local/bin/php",\n        "Xdebug": {\n          "port": 9003,\n          "host": "host.docker.internal"\n        }\n      }\n    }\n  }\n}\n\n# Otevření: Ctrl+Shift+P -> "Dev Containers: Open Folder in Container"</code></pre>', 'lesson', 14, 15, 15),

(@kurs_id, 'Bezpečnost', '<h2>Non-root user</h2><p>Výchozí Docker kontejnery běží jako root — to je bezpečnostní riziko. Vždy vytvoř a používej neprivilegovaného uživatele.</p><pre><code># Dockerfile — non-root user\nFROM php:8.2-apache\n\n# Vytvoření neprivilegovaného uživatele\nRUN groupadd -r appuser &amp;&amp; useradd -r -g appuser appuser\n\n# Nastavení oprávnění před změnou uživatele\nCOPY --chown=appuser:appuser . /var/www/html/\nRUN chown -R appuser:appuser /var/www/html\n\n# Přepnutí na neprivilegovaného uživatele\nUSER appuser\n\nEXPOSE 8080\nCMD ["apache2-foreground"]\n\n# Pozor: Apache výchozí port 80 vyžaduje root\n# Řešení: změň port v Apache config na 8080+</code></pre><h2>Read-only filesystem</h2><pre><code># Read-only root filesystem\ndocker run -d --read-only --tmpfs /tmp --tmpfs /run \\\n  -v app_data:/data \\\n  myapp\n\n# V docker-compose.yml\nservices:\n  php:\n    build: .\n    read_only: true\n    tmpfs:\n      - /tmp\n      - /run\n    volumes:\n      - app_uploads:/var/www/html/uploads\n\nvolumes:\n  app_uploads:</code></pre><h2>Secret management</h2><pre><code># Docker secrets (Swarm mode)\necho "my_secret_password" | docker secret create db_password -\n\ndocker service create \\\n  --name db \\\n  --secret db_password \\\n  -e MYSQL_ROOT_PASSWORD_FILE=/run/secrets/db_password \\\n  mariadb:10.4\n\n# Alternativa — .env soubor (mimo Git!)\n# .env\nDB_ROOT_PASSWORD=super_secret_2024\n\n# .gitignore\n.env\n.env.local\n.env.production\n\n# V docker-compose.yml\nservices:\n  db:\n    environment:\n      MYSQL_ROOT_PASSWORD: ${DB_ROOT_PASSWORD}\n\n# Nebo soubor s tajemstvím\nservices:\n  db:\n    environment:\n      MYSQL_ROOT_PASSWORD_FILE: /run/secrets/db_password\n    secrets:\n      - db_password\n\nsecrets:\n  db_password:\n    file: ./secrets/db_password.txt</code></pre>', 'lesson', 15, 15, 15),

(@kurs_id, 'Resource limits', '<h2>CPU a memory limits</h2><p>Bez limitů může kontejner spotřebovat veškeré zdroje hostitele a způsobit výpadky. Vždy nastav rozumné limity pro CPU i paměť.</p><pre><code># CPU limit — max 1.5 CPU jádra\ndocker run -d --cpus="1.5" myapp\n\n# Memory limit — max 512 MB RAM\ndocker run -d --memory="512m" --memory-swap="512m" myapp\n\n# Kombinace\ndocker run -d \\\n  --cpus="1.0" \\\n  --memory="256m" \\\n  --memory-swap="256m" \\\n  myapp</code></pre><h2>Limits v docker-compose.yml</h2><pre><code>services:\n  php:\n    build: .\n    deploy:\n      resources:\n        limits:\n          cpus: "1.0"\n          memory: 512M\n        reservations:\n          cpus: "0.25"\n          memory: 128M\n\n  db:\n    image: mariadb:10.4\n    deploy:\n      resources:\n        limits:\n          cpus: "2.0"\n          memory: 1G\n        reservations:\n          cpus: "0.5"\n          memory: 256M\n\n  nginx:\n    image: nginx:alpine\n    deploy:\n      resources:\n        limits:\n          cpus: "0.5"\n          memory: 128M\n        reservations:\n          cpus: "0.1"\n          memory: 32M</code></pre><h2>Ulimits</h2><pre><code># Ulimits — systémové limity\n# Omezení počtu otevřených souborů\ndocker run -d --ulimit nofile=65536:65536 myapp\n\n# Core dump limit\ndocker run -d --ulimit core=0:0 myapp\n\n# V docker-compose.yml\nservices:\n  php:\n    build: .\n    ulimits:\n      nofile:\n        soft: 65536\n        hard: 65536\n      nproc:\n        soft: 4096\n        hard: 4096\n\n# Kontrola spotřeby\ndocker stats\ndocker stats --no-stream</code></pre>', 'lesson', 16, 15, 12),

(@kurs_id, 'Health checks', '<h2>HEALTHCHECK instrukce</h2><p>Healthcheck pravidelně kontroluje stav kontejneru. Docker označí kontejner jako "healthy" nebo "unhealthy" podle výsledku kontroly.</p><pre><code># HEALTHCHECK v Dockerfile\nHEALTHCHECK --interval=30s --timeout=5s --start-period=10s --retries=3 \\\n  CMD curl -f http://localhost/ || exit 1\n\n# Pro MariaDB\nHEALTHCHECK --interval=10s --timeout=5s --retries=5 \\\n  CMD mysqladmin ping -h localhost -u root -p$MYSQL_ROOT_PASSWORD || exit 1\n\n# Pro PHP-FPM\nHEALTHCHECK --interval=30s --timeout=3s --retries=3 \\\n  CMD cgi-fcgi -bind -connect localhost:9000 || exit 1\n\n# Vypnutí healthchecku\nHEALTHCHECK NONE</code></pre><h2>Healthcheck v docker run</h2><pre><code># Přezdění výchozího healthchecku\ndocker run -d --name myapp \\\n  --health-cmd "curl -f http://localhost/health || exit 1" \\\n  --health-interval 30s \\\n  --health-timeout 5s \\\n  --health-retries 3 \\\n  --health-start-period 10s \\\n  myimage\n\n# Kontrola stavu\ndocker inspect --format="{{.State.Health.Status}}" myapp\n# healthy / unhealthy / starting\n\n# Detail healthcheck logů\ndocker inspect --format="{{json .State.Health}}" myapp | jq</code></pre><h2>Restart policies</h2><p>Restart policy určuje, co se stane po pádu kontejneru. <code>unless-stopped</code> je nejbezpečnější volba — restartuje po pádu, ale ne po <code>docker stop</code>.</p><pre><code># no — nikdy nerestartuje (výchozí)\ndocker run -d --restart=no myapp\n\n# always — restartuje vždy (i po docker restart, i po reboot hostitele)\ndocker run -d --restart=always myapp\n\n# unless-stopped — restartuje, kromě explicitního docker stop\ndocker run -d --restart=unless-stopped myapp\n\n# on-failure — restartuje jen při nenulovém exit kódu\ndocker run -d --restart=on-failure:5 myapp  # max 5 pokusů\n\n# V docker-compose.yml\nservices:\n  db:\n    image: mariadb:10.4\n    restart: unless-stopped\n\n  php:\n    build: .\n    restart: unless-stopped\n\n  nginx:\n    image: nginx:alpine\n    restart: always</code></pre>', 'lesson', 17, 15, 13),

(@kurs_id, 'Orchestrace intro', '<h2>Kubernetes základy</h2><p>Kubernetes (K8s) je orchestrátor kontejnerů v produkčním měřítku. Spravuje nasazení, škálování, sítě a dostupnost. Pro malé projekty je Docker Compose dostačující, ale pro produkci s vysokou dostupností je K8s standard.</p><pre><code># Základní K8s objekty\n# Pod — nejmenší nasaditelná jednotka (1+ kontejnerů)\n# Deployment — deklarativní správa replik Podů\n# Service — stabilní síťová identita pro Pody\n# ConfigMap / Secret — konfigurace a tajemství\n# Ingress — HTTP routing zvenčí do Service\n\n# Minimální deployment\napiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: edu-php\nspec:\n  replicas: 2\n  selector:\n    matchLabels:\n      app: edu-php\n  template:\n    metadata:\n      labels:\n        app: edu-php\n    spec:\n      containers:\n      - name: php\n        image: ghcr.io/vevit/edu-php:latest\n        ports:\n        - containerPort: 80\n        resources:\n          limits:\n            memory: "512Mi"\n            cpu: "1"\n\n---\napiVersion: v1\nkind: Service\nmetadata:\n  name: edu-php-svc\nspec:\n  selector:\n    app: edu-php\n  ports:\n  - port: 80\n    targetPort: 80\n  type: ClusterIP</code></pre><h2>Docker Swarm</h2><p>Docker Swarm je jednodušší alternativa k Kubernetes — vestavěná v Dockeru. Pro menší produkce je dostačující.</p><pre><code># Inicializace Swarmu\ndocker swarm init\n\n# Nasazení stacku\ndocker stack deploy -c docker-compose.yml vevit\n\n# Seznam služeb\ndocker service ls\n\n# Škálování služby\ndocker service scale vevit_php=3\n\n# Aktualizace služby (rolling update)\ndocker service update --image ghcr.io/vevit/edu-php:v2.0 vevit_php\n\n# Swarm secrets\necho "my_password" | docker secret create db_pwd -\ndocker service create --name db --secret db_pwd mariadb:10.4\n\n# Swarm limits v compose\nservices:\n  php:\n    image: ghcr.io/vevit/edu-php:latest\n    deploy:\n      replicas: 2\n      update_config:\n        parallelism: 1\n        delay: 10s\n      restart_policy:\n        condition: on-failure\n      resources:\n        limits:\n          cpus: "1.0"\n          memory: 512M</code></pre>', 'lesson', 18, 15, 15),

(@kurs_id, 'CI/CD s Dockerem', '<h2>GitHub Actions — build a push</h2><p>Automatizuj build Docker image, push do registry a deployment pomocí GitHub Actions. Každý push na main spustí pipeline.</p><pre><code># .github/workflows/docker-ci.yml\nname: Docker CI/CD\n\non:\n  push:\n    branches: [main]\n  pull_request:\n    branches: [main]\n\nenv:\n  REGISTRY: ghcr.io\n  IMAGE: vevit/edu-php\n\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: docker/build-push-action@v5\n        with:\n          context: .\n          push: false\n          load: true\n          tags: ${{ env.IMAGE }}:test\n      - name: Run tests inside container\n        run: |\n          docker run --rm ${{ env.IMAGE }}:test php vendor/bin/phpunit\n\n  build-push:\n    needs: test\n    runs-on: ubuntu-latest\n    if: github.event_name == ''push'' &amp;&amp; github.ref == ''refs/heads/main''\n    permissions:\n      contents: read\n      packages: write\n    steps:\n      - uses: actions/checkout@v4\n      - uses: docker/login-action@v3\n        with:\n          registry: ${{ env.REGISTRY }}\n          username: ${{ github.actor }}\n          password: ${{ secrets.GITHUB_TOKEN }}\n      - uses: docker/metadata-action@v5\n        id: meta\n        with:\n          images: ${{ env.REGISTRY }}/${{ env.IMAGE }}\n          tags: |\n            type=sha\n            type=raw,value=latest\n      - uses: docker/build-push-action@v5\n        with:\n          context: .\n          push: true\n          tags: ${{ steps.meta.outputs.tags }}\n          cache-from: type=gha\n          cache-to: type=gha,mode=max</code></pre><h2>Deployment na server</h2><pre><code># .github/workflows/deploy.yml (přidáno k předchozímu)\n  deploy:\n    needs: build-push\n    runs-on: ubuntu-latest\n    steps:\n      - name: Deploy via SSH\n        uses: appleboy/ssh-action@v1\n        with:\n          host: ${{ secrets.SERVER_HOST }}\n          username: ${{ secrets.SERVER_USER }}\n          key: ${{ secrets.SSH_PRIVATE_KEY }}\n          script: |\n            cd /opt/vevit\n            docker compose pull php\n            docker compose up -d --remove-orphans\n            docker image prune -f\n\n# Na serveru: /opt/vevit/docker-compose.yml\n# Obsahuje odkaz na ghcr.io/vevit/edu-php:latest\n\n# Watchtower — automatický update\n# Nasadí novou verzi image automaticky po push do registry\ndocker run -d \\\n  --name watchtower \\\n  -v /var/run/docker.sock:/var/run/docker.sock \\\n  -e WATCHTOWER_CLEANUP=true \\\n  -e WATCHTOWER_INTERVAL=300 \\\n  containrrr/watchtower</code></pre>', 'lesson', 19, 15, 15),

(@kurs_id, 'VeVit deployment', '<h2>Kompletní VeVit ekosystém</h2><p>Následující docker-compose.yml definuje kompletní produkční stack pro ekosystém vevit.fun — Apache/PHP pro edu.vevit.fun, MariaDB databáze a Nginx reverse proxy s SSL termination.</p><pre><code># /opt/vevit/docker-compose.yml — VeVit produkční stack\nversion: "3.8"\n\nservices:\n  # ============================================\n  # Apache + PHP pro edu.vevit.fun\n  # ============================================\n  php:\n    build:\n      context: ./php\n      dockerfile: Dockerfile\n    container_name: vevit-php\n    restart: unless-stopped\n    volumes:\n      - vevit_html:/var/www/html\n      - ./php/src:/var/www/html:ro\n      - ./php/conf/vhost.conf:/etc/apache2/sites-available/000-default.conf:ro\n      - ./php/conf/php.ini:/usr/local/etc/php/conf.d/custom.ini:ro\n    environment:\n      DB_HOST: db\n      DB_PORT: 3306\n      DB_NAME: ${DB_NAME}\n      DB_USER: ${DB_USER}\n      DB_PASSWORD: ${DB_PASSWORD}\n      APP_ENV: ${APP_ENV}\n      APP_DEBUG: ${APP_DEBUG}\n      VEVIT_SECRET: ${VEVIT_SECRET}\n    depends_on:\n      db:\n        condition: service_healthy\n    networks:\n      - frontend\n      - backend\n    healthcheck:\n      test: ["CMD", "curl", "-f", "http://localhost/"]\n      interval: 30s\n      timeout: 5s\n      retries: 3\n      start_period: 15s\n    deploy:\n      resources:\n        limits:\n          cpus: "1.0"\n          memory: 512M\n        reservations:\n          cpus: "0.25"\n          memory: 128M\n\n  # ============================================\n  # MariaDB databáze\n  # ============================================\n  db:\n    image: mariadb:10.4\n    container_name: vevit-db\n    restart: unless-stopped\n    volumes:\n      - vevit_db_data:/var/lib/mysql\n      - ./database:/docker-entrypoint-initdb.d:ro\n    environment:\n      MYSQL_ROOT_PASSWORD: ${DB_ROOT_PASSWORD}\n      MYSQL_DATABASE: ${DB_NAME}\n      MYSQL_USER: ${DB_USER}\n      MYSQL_PASSWORD: ${DB_PASSWORD}\n      MYSQL_CHARACTER_SET_SERVER: utf8mb4\n      MYSQL_COLLATION_SERVER: utf8mb4_unicode_ci\n    networks:\n      - backend\n    # Není vystaven port — přístup jen přes backend síť\n    healthcheck:\n      test: ["CMD", "mysqladmin", "ping", "-h", "localhost", "-u", "root", "-p${DB_ROOT_PASSWORD}"]\n      interval: 10s\n      timeout: 5s\n      retries: 10\n      start_period: 30s\n    deploy:\n      resources:\n        limits:\n          cpus: "2.0"\n          memory: 1G\n        reservations:\n          cpus: "0.5"\n          memory: 256M\n\n  # ============================================\n  # Nginx reverse proxy + SSL termination\n  # ============================================\n  nginx:\n    image: nginx:alpine\n    container_name: vevit-nginx\n    restart: unless-stopped\n    ports:\n      - "80:80"\n      - "443:443"\n    volumes:\n      - ./nginx/conf.d:/etc/nginx/conf.d:ro\n      - ./nginx/ssl:/etc/nginx/ssl:ro\n      - certbot_webroot:/var/www/certbot:ro\n      - vevit_html:/var/www/html:ro\n    depends_on:\n      php:\n        condition: service_healthy\n    networks:\n      - frontend\n    healthcheck:\n      test: ["CMD", "wget", "--quiet", "--tries=1", "--spider", "http://localhost/"]\n      interval: 30s\n      timeout: 5s\n      retries: 3\n    deploy:\n      resources:\n        limits:\n          cpus: "0.5"\n          memory: 128M\n        reservations:\n          cpus: "0.1"\n          memory: 32M\n\n  # ============================================\n  # Certbot — automatické obnovování SSL\n  # ============================================\n  certbot:\n    image: certbot/certbot\n    container_name: vevit-certbot\n    volumes:\n      - certbot_webroot:/var/www/certbot\n      - certbot_certs:/etc/letsencrypt\n    entrypoint: "/bin/sh -c ''trap exit TERM; while :; do certbot renew; sleep 12h &amp; wait $${!}; done;''"\n    networks:\n      - frontend\n\n# ============================================\n# Sítě\n# ============================================\nnetworks:\n  frontend:\n    driver: bridge\n  backend:\n    driver: bridge\n    internal: true\n\n# ============================================\n# Volumes\n# ============================================\nvolumes:\n  vevit_db_data:\n    driver: local\n  vevit_html:\n    driver: local\n  certbot_webroot:\n    driver: local\n  certbot_certs:\n    driver: local</code></pre><h2>PHP Dockerfile</h2><pre><code># php/Dockerfile\nFROM php:8.2-apache\n\nRUN a2enmod rewrite headers\n\nRUN apt-get update &amp;&amp; apt-get install -y \\\n    libpng-dev libjpeg62-turbo-dev libfreetype6-dev \\\n    libzip-dev curl \\\n    &amp;&amp; rm -rf /var/lib/apt/lists/* \\\n    &amp;&amp; docker-php-ext-configure gd --with-freetype --with-jpeg \\\n    &amp;&amp; docker-php-ext-install gd pdo pdo_mysql zip\n\nCOPY . /var/www/html/\nRUN chown -R www-data:www-data /var/www/html\n\nEXPOSE 80\nCMD ["apache2-foreground"]</code></pre><h2>Nginx konfigurace pro edu.vevit.fun</h2><pre><code># nginx/conf.d/vevit.conf\nupstream php_backend {\n    server php:80;\n}\n\nserver {\n    listen 80;\n    server_name edu.vevit.fun;\n\n    location /.well-known/acme-challenge/ {\n        root /var/www/certbot;\n    }\n\n    location / {\n        return 301 https://$host$request_uri;\n    }\n}\n\nserver {\n    listen 443 ssl http2;\n    server_name edu.vevit.fun;\n\n    ssl_certificate /etc/nginx/ssl/live/edu.vevit.fun/fullchain.pem;\n    ssl_certificate_key /etc/nginx/ssl/live/edu.vevit.fun/privkey.pem;\n    ssl_protocols TLSv1.2 TLSv1.3;\n    ssl_ciphers HIGH:!aNULL:!MD5;\n    ssl_prefer_server_ciphers on;\n\n    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;\n    add_header X-Content-Type-Options nosniff always;\n    add_header X-Frame-Options SAMEORIGIN always;\n\n    location / {\n        proxy_pass http://php_backend;\n        proxy_set_header Host $host;\n        proxy_set_header X-Real-IP $remote_addr;\n        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;\n        proxy_set_header X-Forwarded-Proto $scheme;\n        proxy_connect_timeout 60s;\n        proxy_read_timeout 120s;\n    }\n\n    location ~ /\\. {\n        deny all;\n    }\n}</code></pre><h2>Env soubor a spuštění</h2><pre><code># .env (NEcommitovat!)\nDB_ROOT_PASSWORD=super_strong_root_pass\nDB_NAME=vevit_db\nDB_USER=vevit_user\nDB_PASSWORD=vevit_app_password\nAPP_ENV=production\nAPP_DEBUG=false\nVEVIT_SECRET=your_hmac_secret_key_here\n\n# .env.example (commitovat)\nDB_ROOT_PASSWORD=change_me\nDB_NAME=vevit_db\nDB_USER=vevit_user\nDB_PASSWORD=change_me\nAPP_ENV=production\nAPP_DEBUG=false\nVEVIT_SECRET=change_me\n\n# Spuštění celého stacku\ncp .env.example .env\n# Uprav .env hesla!\ndocker compose up -d\n\n# Kontrola\ndocker compose ps\ndocker compose logs -f\n\n# Získání SSL certifikátu\ndocker compose run --rm certbot certonly \\\n  --webroot --webroot-path /var/www/certbot \\\n  -d edu.vevit.fun \\\n  --email admin@vevit.fun \\\n  --agree-tos --no-eff-email</code></pre>', 'lesson', 20, 15, 20),


