INSERT INTO lessons (course_id, title, content, lesson_type, sort_order, xp_reward, duration_minutes) VALUES
(@kurs_id, 'Závěrečný kvíz — Celý Docker kurz', '<p>Závěrečný test pokrývající všechny sekce kurzu Docker — od základů kontejnerizace přes Dockerfile, Compose, sítě, volumes až po produkční deployment.</p>', 'final_quiz', 21, 200, 30);

SET @qfin = LAST_INSERT_ID();

INSERT INTO quizzes (lesson_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, sort_order) VALUES
(@qfin, 'Jaký je hlavní rozdíl mezi kontejnerem a virtuálním strojem?', 'Kontejner má vlastní OS jádro', 'Kontejner sdílí jádro hostitele, VM má vlastní OS', 'Kontejner nelze připojit k síti', 'VM je vždy menší než kontejner', 'b', 'Kontejner sdílí jádro hostitelského OS, zatímco VM běží na vlastním plném operačním systému s vlastním jádrem.', 1),
(@qfin, 'Která Docker instrukce v Dockerfile definuje výchozí příkaz při spuštění kontejneru?', 'RUN', 'ENTRYPOINT', 'CMD', 'EXEC', 'c', 'CMD definuje výchozí příkaz a argumenty pro spuštění kontejneru. ENTRYPOINT nastavuje neměnný vstupní bod.', 2),
(@qfin, 'K čemu slouží multi-stage build v Dockerfile?', 'Paralelní spuštění více kontejnerů', 'Vytvoření více sítí', 'Oddělení build fáze od produkčního image pro zmenšení velikosti', 'Automatické testování během buildu', 'c', 'Multi-stage build používá více FROM instrukcí — build závislosti zůstávají v předchozích fázích a finální image obsahuje jen produkční artefakty.', 3),
(@qfin, 'Jaký typ Docker volume je vhodný pro vývoj s live reload?', 'Named volume', 'tmpfs mount', 'Bind mount', 'Anonymous volume', 'c', 'Bind mount připojuje adresář hostitele do kontejneru — změny souborů na hostiteli se okamžitě projeví v kontejneru.', 4),
(@qfin, 'Jak kontejnery komunikují na vlastní Docker síti?', 'Pouze přes IP adresy', 'Pomocí názvů služeb přes vestavěný DNS', 'Pomocí MAC adres', 'Přes sdílený souborový systém', 'b', 'Na vlastní bridge síti Docker poskytuje DNS — kontejnery se mohou referencovat pomocí názvu služby.', 5),
(@qfin, 'Co dělá depends_on s condition: service_healthy v docker-compose.yml?', 'Čeká, až závislá služba nastartuje', 'Čeká, až závislá služba projde healthcheckem', 'Zastaví závislou službu po startu', 'Vytvoří novou síť', 'b', 'condition: service_healthy čeká, až závislá služba úspěšně projde healthcheck — zaručuje, že je skutečně připravena.', 6),
(@qfin, 'Který příkaz zálohuje MariaDB databázi běžící v Docker kontejneru?', 'docker backup vevit-db', 'docker exec vevit-db mysqldump --all-databases -uroot -pSECRET > backup.sql', 'docker save vevit-db > backup.sql', 'docker compose export db', 'b', 'docker exec spustí mysqldump uvnitř běžícího kontejneru — výsledný SQL se přesměruje do souboru na hostiteli.', 7),
(@qfin, 'Jaký je účel Nginx reverse proxy ve VeVit stacku?', 'Nahrazuje Apache jako PHP server', 'Přijímá požadavky zvenčí, poskytuje SSL termination a proxyuje na backend', 'Slouží jako databázový server', 'Nahrazuje Docker Compose', 'b', 'Reverse proxy zpracovává SSL termination, bezpečnostní hlavičky a přesměrovává požadavky na backend kontejnery — ty nejsou vystaveny přímo.', 8),
(@qfin, 'Proč používat non-root user v Docker kontejneru?', 'Zrychluje start kontejneru', 'Snižuje bezpečnostní riziko — pokud útočník prolomí kontejner, nemá root práva', 'Šetří paměť', 'Je vyžadováno Docker Hubem', 'b', 'Běh jako neprivilegovaný uživatel omezuje dopad bezpečnostního průniku — útočník nemá root přístup uvnitř kontejneru.', 9),
(@qfin, 'Jak restart_policy unless-stopped funguje v docker-compose.yml?', 'Restartuje kontejner vždy, i po docker stop', 'Restartuje po pádu, ale ne po explicitním docker stop', 'Nikdy nerestartuje kontejner', 'Restartuje kontejner jen při rebootu hostitele', 'b', 'unless-stopped restartuje kontejner po pádu nebo rebootu hostitele, ale respektuje explicitní docker stop — kontejner se po rebootu nespustí, pokud byl předtím zastaven přes docker stop.', 10);


